def get_first_pixel_v2(grid):
    R, C = len(grid), len(grid[0])
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and grid[r][c] != 5:
                return (r, c, grid[r][c])
    return None

def demo_first(ranges, grid_list):
    result = []
    for r in ranges:
        first = get_first_pixel_v2(grid_list[r])
        result.append(first)
    return result

